import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseBai2 } from '../../src/bai2/index.js';
import { verifyPublicSamples } from '../../scripts/verify-public-bai2.js';

/**
 * The files in `samples/public/` were published by banks, not generated by this project. A test
 * here is therefore a check of the reader against bytes we did not choose (`samples/public/SOURCES.md`
 * records where each one came from).
 */
describe('the reader against published BAI2 files', () => {
  it('parses the Westpac NPP sample with no issues and exact trailer totals', () => {
    const result = parseBai2(readFileSync(join('samples', 'public', 'bai2-westpac-npp.txt')));
    expect(result.issues).toEqual([]);
    expect(result.eol).toBe('\r\n');
    expect(result.computedControl.recordCount).toBe(27);
    expect(result.computedControl.detailCount).toBe(10);
    expect(result.declaredControl?.total).toMatchObject({ minorUnits: 4_000_000n, currency: 'AUD', scale: 2 });
    // The `100` total credits code sits at the end of the `03` record, and its amount is the first
    // field of the following `88`. Reading only the first summary of an `03` used to miss it.
    expect(result.declaredControl?.recordIndex).toBe(3);
  });

  it('parses the SouthState guide sample with four accounts in one group and no issues', () => {
    const result = parseBai2(readFileSync(join('samples', 'public', 'bai2-southstate-guide.txt')));
    expect(result.issues).toEqual([]);
    expect(result.computedControl.recordCount).toBe(27);
    expect(result.computedControl.detailCount).toBe(12);
    expect(result.declaredControl?.total).toMatchObject({ minorUnits: 20_042_948n, currency: 'USD', scale: 2 });
    const accounts = result.records.filter((record) => record.values['REC-CODE'] === '03');
    expect(accounts).toHaveLength(4);
  });

  it('the verification script agrees: every published file parses cleanly', () => {
    const rows = verifyPublicSamples();
    expect(rows).toHaveLength(2);
    for (const row of rows) expect({ file: row.file, problems: row.problems }).toEqual({ file: row.file, problems: [] });
  });
});
